<?php
require 'config/functions.php'; require 'config/database.php';
$id=(int)($_GET['id']??0); $r=['first_name'=>'','middle_name'=>'','last_name'=>'','birth_date'=>'','sex'=>'','phone'=>'','email'=>'','address'=>'','household_id'=>'','status'=>'Active'];
