<div class="field"><label>First name *</label><input name="first_name" required maxlength="80" value="<?=e($r['first_name'])?>"></div><div class="field"><label>Middle name</label><input name="middle_name" maxlength="80" value="<?=e($r['middle_name'])?>"></div>
<div class="field"><label>Last name *</label><input name="last_name" required maxlength="80" value="<?=e($r['last_name'])?>"></div><div class="field"><label>Birth date</label><input type="date" name="birth_date" value="<?=e($r['birth_date'])?>"></div>
<div class="field"><label>Sex</label><select name="sex"><option value="">Select</option><?php foreach(['Female','Male','Prefer not to say'] as $v):?><option value="<?=e($v)?>" <?=($r['sex']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="field"><label>Phone number</label><input name="phone" maxlength="30" value="<?=e($r['phone'])?>"></div>
<div class="field"><label>Email</label><input type="email" name="email" maxlength="150" value="<?=e($r['email'])?>"></div><div class="field"><label>Household</label><select name="household_id"><option value="">Not assigned</option><?php foreach($houses as $h):?><option value="<?=$h['id']?>" <?=($r['household_id']??'')==$h['id']?'selected':''?>><?=e($h['household_code'].' — '.$h['address'])?></option><?php endforeach;?></select></div>
<div class="field full"><label>Complete address *</label><textarea name="address" required maxlength="255"><?=e($r['address'])?></textarea></div><div class="field"><label>Resident status</label><select name="status"><?php foreach(['Active','Inactive','Moved','Deceased'] as $v):?><option <?=($r['status']??'Active')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div></div><div class="actions" style="justify-content:flex-start"><button class="btn primary">Save Resident</button><a class="btn" style="background:#edf1f7" href="residents.php">Cancel</a></div></form></div></main><?php end_page(); ?>
